-- Десять вопросов раздела «06. Очистка» по сверке с лекцией: размер выборки ANALYZE, VACUUM без списка таблиц, pgstattuple после очистки, pgstattuple_approx, уплотнение разросшегося индекса, сбой REINDEX CONCURRENTLY, индексы EXCLUDE, место на диске для VACUUM FULL, очистка после каждого изменения, autovacuum_enabled; пояснения к каждому варианту.
-- Источник: scripts/questions/137_vacuum_lecture.js
-- Повторный запуск безопасен; несовпадение ранее добавленного вопроса отменяет пакет.
-- https://www.postgresql.org/docs/16/sql-analyze.html
-- https://www.postgresql.org/docs/16/runtime-config-query.html
-- https://www.postgresql.org/docs/16/sql-vacuum.html
-- https://www.postgresql.org/docs/16/app-vacuumdb.html
-- https://www.postgresql.org/docs/16/pgstattuple.html
-- https://www.postgresql.org/docs/16/routine-vacuuming.html
-- https://www.postgresql.org/docs/16/sql-reindex.html
-- https://www.postgresql.org/docs/16/sql-createtable.html

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO question_seed
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблица events — 50 млн строк. default_statistics_target по умолчанию (100), ориентиры статистики для столбцов, индексов и объектов расширенной статистики не меняли. Сколько строк ANALYZE events возьмёт в выборку?', '{"A":"Около 100: по строке на единицу параметра","B":"Около 30 000: в 300 раз больше значения параметра","C":"Все 50 млн: статистика строится по всем строкам","D":"Около 500 000: один процент строк таблицы"}'::jsonb, 'B', 'Выборку считают по наибольшему ориентиру статистики среди столбцов таблицы, индексов по выражениям и объектов расширенной статистики: в опыте при SET STATISTICS 500 у одного столбца в выборку попало 150 000 строк. Статистика по выборке неточная, но этого и не требуется.', '{"A":"Значение параметра ограничивает число частых значений и корзин гистограммы, а выборка в 300 раз больше.","B":"Размер выборки — 300 × ориентир статистики, здесь 300 × 100. В опыте ANALYZE VERBOSE по таблице в миллион строк показал «строк в выборке: 30000».","C":"Анализ читает случайную выборку, поэтому быстро обрабатывает и очень большие таблицы.","D":"У большой таблицы размер выборки не зависит от числа строк: его задаёт ориентир статистики."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'В кластере две базы: appdb и crm. Суперпользователь, подключённый к appdb, выполнил VACUUM ANALYZE без имён таблиц. Что будет обработано?', '{"A":"Все таблицы appdb, включая системный каталог","B":"Таблицы схемы public базы appdb, без каталога","C":"Все таблицы обеих баз кластера: appdb и crm","D":"Таблицы appdb, где статистика видит мёртвые версии"}'::jsonb, 'A', 'Обёртка vacuumdb подключается к указанной базе и выполняет ту же команду VACUUM. С ключом --all она по очереди обходит все базы кластера, с --analyze добавляет анализ.', '{"A":"Без списка таблиц команда обрабатывает все таблицы текущей базы. В опыте last_vacuum появился и у пользовательских таблиц, и у таблиц pg_catalog.","B":"Обрабатываются таблицы всех схем базы, системный каталог тоже.","C":"SQL-команда работает в текущей базе. Все базы кластера обработает обёртка vacuumdb --all.","D":"Ручная команда не выбирает таблицы по статистике, как автоочистка, а обрабатывает все."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблица bloat — 6,6 МБ, автоочистка для неё отключена, других сеансов нет. После UPDATE каждой второй строки pgstattuple(''bloat'') показал: tuple_percent 60, dead_tuple_percent 30, free_percent 0,3. Выполнили VACUUM bloat. Что покажет pgstattuple теперь?', '{"A":"table_len около 4,4 МБ","B":"dead_tuple_percent около 0","C":"tuple_percent около 90","D":"free_percent около 30"}'::jsonb, 'BD', 'Числа из опыта по демонстрации курса: в таблице 100 000 строк изменили половину, размер вырос в полтора раза. VACUUM перевёл 30 % объёма из мёртвых версий в свободное место, table_len остался прежним, 6 643 712 байт. К исходным 4,4 МБ таблицу вернула VACUUM FULL.', '{"A":"Обычная очистка не переписывает таблицу: живые версии остаются на своих страницах, а мёртвые были разбросаны по всему файлу. Отрезать можно лишь полностью пустые страницы в конце.","B":"Очистка удалила мёртвые версии строк из страниц таблицы.","C":"Живые версии остались на месте и занимают ту же долю файла: в опыте 60,21 % до очистки и после.","D":"Место мёртвых версий стало свободным внутри страниц и пойдёт под новые версии строк."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблица 500 ГБ, VACUUM по ней прошёл час назад. pgstattuple_approx отработал за секунды и показал scanned_percent = 3. Почему так быстро?', '{"A":"Пропустила страницы, отмеченные в карте видимости","B":"Прочитала случайные 3 % страниц, как ANALYZE","C":"Прочитала первые 3 % страниц и пересчитала на всю","D":"Взяла число мёртвых версий из pg_stat_user_tables"}'::jsonb, 'A', 'В опыте сразу после VACUUM pgstattuple_approx показала scanned_percent = 0, а после изменения половины строк — 100: UPDATE снял отметки со всех страниц. Точные числа даёт pgstattuple, но она читает всю таблицу.', '{"A":"На таких страницах функция считает, что мёртвых версий нет, а их свободное место берёт из карты свободного пространства.","B":"Случайной выборки функция не делает: она читает все страницы, не отмеченные в карте видимости.","C":"Функция не экстраполирует по началу файла: она пропускает отмеченные страницы, где бы они ни лежали.","D":"Накопительная статистика ей не нужна: результат считается по страницам таблицы и её картам."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблицу bloat очистили VACUUM, но pgstatindex(''bloat_d_idx'') — обычного индекса B-дерева по столбцу d — показывает 133 листовые страницы вместо 85 сразу после создания и avg_leaf_density 58 %. Какие команды перестроят индекс, уплотнив полупустые страницы?', '{"A":"VACUUM ANALYZE bloat","B":"VACUUM FULL bloat","C":"VACUUM (INDEX_CLEANUP ON) bloat","D":"REINDEX INDEX CONCURRENTLY bloat_d_idx"}'::jsonb, 'BD', 'Расщеплённые страницы B-дерева не объединяются, даже когда записей в них стало мало, поэтому индекс может остаться разросшимся и при чистой таблице. Если разросся только индекс, хватит REINDEX: с CONCURRENTLY он не блокирует изменение таблицы, а VACUUM FULL блокирует даже чтение.', '{"A":"Очистка с анализом индекс не перестраивает; статистика на размер файла не влияет.","B":"Полная очистка переписывает таблицу и заново строит все её индексы, но на это время блокирует таблицу целиком.","C":"INDEX_CLEANUP ON запрашивает очистку индексов: она убирает ссылки на мёртвые версии, но не перестраивает B-дерево и не объединяет полупустые страницы.","D":"Индекс строится заново, записи укладываются плотно; итоговый размер зависит от текущих данных. В опыте снова 85 листовых страниц и плотность 89 %."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'REINDEX INDEX CONCURRENTLY big_v_idx прервался по statement_timeout. В \d big теперь два индекса: big_v_idx и big_v_idx_ccnew INVALID. Что делать?', '{"A":"Перестроить big_v_idx_ccnew, он заменит big_v_idx","B":"Удалить big_v_idx: запросы уже работают с копией","C":"Ничего: копию удалит следующая очистка таблицы","D":"Удалить big_v_idx_ccnew и повторить перестроение"}'::jsonb, 'D', 'Неблокирующее перестроение идёт в несколько транзакций, поэтому сбой откатывает не всё: остаётся индекс с суффиксом _ccnew, помеченный INVALID. Если остался индекс с суффиксом _ccold, это прежний индекс: перестроение прошло, и его просто удаляют.', '{"A":"REINDEX сделает копию действующей, и у таблицы будет два одинаковых индекса: в опыте так и вышло.","B":"Наоборот: действующий индекс — big_v_idx, а индекс INVALID планировщик не использует.","C":"VACUUM и автоочистка индексы не удаляют, копия останется, пока её не удалят вручную.","D":"Это недостроенная копия. DROP INDEX её убирает, и REINDEX CONCURRENTLY можно запустить снова."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'У таблицы bookings четыре индекса. Какой из них не удастся перестроить командой REINDEX INDEX CONCURRENTLY?', '{"A":"Индекс ограничения EXCLUDE по периоду брони","B":"Индекс по выражению lower(guest_email)","C":"Индекс первичного ключа по столбцу booking_id","D":"Уникальный индекс по номеру брони и дате"}'::jsonb, 'A', 'Кроме индексов ограничений-исключений, неблокирующим способом нельзя перестроить индексы системного каталога. REINDEX TABLE CONCURRENTLY bookings пропускает индекс EXCLUDE с предупреждением и перестраивает остальные.', '{"A":"Неблокирующее перестроение индексов ограничений-исключений не поддерживается: в опыте команда завершилась ошибкой.","B":"Индексы по выражению перестраиваются неблокирующим способом, в опыте без ошибок.","C":"Индексы первичного ключа перестраиваются неблокирующим способом, в опыте без ошибок.","D":"Уникальные индексы тоже перестраиваются неблокирующим способом, в опыте без ошибок."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблица orders и её индексы занимают на одном томе 400 ГБ, после перестройки они заняли бы около 160 ГБ. Свободно 50 ГБ. Чем рискует VACUUM FULL orders?', '{"A":"Ничем: мёртвые версии сначала удаляются на месте","B":"Ничем: страницы переносятся и сразу освобождаются","C":"Места не хватит: старые файлы удаляются только в конце","D":"Ничем: команда заранее проверит, хватит ли места"}'::jsonb, 'C', 'Полная очистка складывает живые версии строк в новый набор файлов и удаляет старый только в конце, индексы строятся заново. Поэтому ей нужно свободное место под новую копию таблицы с индексами. Если том общий с pg_wal, нехватка места грозит всему серверу.', '{"A":"VACUUM FULL не чистит таблицу на месте, а пишет живые версии в новые файлы.","B":"Старые файлы удаляются после завершения команды, до этого на диске лежат обе копии.","C":"Команда пишет новую копию таблицы и индексов рядом со старой: нужно около 160 ГБ, а свободно 50.","D":"Предварительной проверки нет: когда место кончится, команда завершится ошибкой и откатится."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Таблица t (n numeric) — 100 000 случайных чисел от 0 до 1, 4,3 МБ, автоочистка выключена, других сеансов нет. Четыре раза подряд выполняют UPDATE t SET n = n WHERE n < 0.5 и после каждого — VACUUM t. Каким будет размер таблицы после четвёртого раза?', '{"A":"Около 8,7 МБ: VACUUM отстаёт на одно изменение","B":"Около 6,5 МБ, как после первого раза","C":"Около 4,3 МБ, как до изменений","D":"Около 13 МБ: каждый раз плюс 2,2 МБ"}'::jsonb, 'B', 'Это опыт из практики курса. Обычная очистка, как правило, не уменьшает файлы, но останавливает их рост: место мёртвых версий занимают новые. В опыте после каждого из четырёх раз было 6536 kB.', '{"A":"Очистка после UPDATE удаляет все мёртвые версии этого UPDATE: снимков, которые их удерживают, нет.","B":"После первого изменения таблица вырастает, дальше новые версии занимают место, освобождённое очисткой.","C":"Очистка не возвращает ОС место внутри страниц, а отрезать может лишь полностью пустые страницы в конце файла: в опыте размер после первого раза не менялся.","D":"Так растёт таблица без очистки: в опыте 4,3 → 6,5 → 8,7 → 11 МБ после трёх изменений."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '06.'), 'Допишите команду, чтобы отключить автоочистку только для таблицы bloat, как в демонстрации курса:
```
ALTER TABLE bloat SET (___ = off);
```', '{"A":"`vacuum_truncate`","B":"`autovacuum`","C":"`autovacuum_enabled`","D":"`toast.autovacuum_enabled`"}'::jsonb, 'C', 'С autovacuum_enabled = off автоочистка не обрабатывает таблицу в обычном режиме, но всё равно придёт, когда понадобится защита от переполнения счётчика транзакций. На практике так делать не рекомендуется: в демонстрации это нужно, чтобы очистка не сработала в случайный момент.', '{"A":"Параметр отключает отрезание пустых страниц в конце файла при очистке, а не саму автоочистку.","B":"Это параметр сервера, у таблицы такого параметра нет: в опыте ошибка «нераспознанный параметр».","C":"Это параметр хранения таблицы, остальные таблицы автоочистка обрабатывает как обычно.","D":"Так автоочистка отключается для toast-таблицы, а основная таблица обрабатывается по-прежнему."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 10 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
